# Synthetic LLM-08 fixture: threshold and identity boundaries. Never executed.
import anthropic

claude = anthropic.Anthropic()
AT_LIMIT = "Classify the ticket. "
OVER_LIMIT = "Classify the ticket. "


def cap_at_limit(messages):
    return claude.messages.create(model="claude-opus-5-5", max_tokens=256, messages=messages)


def cap_over_limit(messages):
    return claude.messages.create(model="claude-opus-5-5", max_tokens=257, messages=messages)


def prompt_at_limit(messages):
    return claude.messages.create(model="claude-opus-5-5", max_tokens=4096, system=AT_LIMIT, messages=messages)


def prompt_over_limit(messages):
    return claude.messages.create(model="claude-opus-5-5", max_tokens=4096, system=OVER_LIMIT, messages=messages)


def twice(first, second):
    claude.messages.create(model="claude-opus-5-5", max_tokens=1, messages=first)
    return claude.messages.create(model="claude-opus-5-5", max_tokens=1, messages=second)
